--sistem

function vec2(x, y) end

local meta = {
 __add = function(a, b)if type(b)==type({}) then return vec2(a.x+b.x,a.y+b.y) else return vec2(a.x+b,a.y+b) end end,
 __sub = function(a, b)if type(b)==type({}) then return vec2(a.x-b.x,a.y-b.y) else return vec2(a.x-b,a.y-b) end end,
 __mul = function(a, b)if type(b)==type({}) then return vec2(a.x*b.x,a.y*b.y) else return vec2(a.x*b,a.y*b) end end,
 __div = function(a, b)if type(b)==type({}) then return vec2(a.x/b.x,a.y/b.y) else return vec2(a.x/b,a.y/b) end end,
 __mod = function(a, b)if type(b)==type({}) then return vec2(a.x%b.x,a.y%b.y) else return vec2(a.x%b,a.y%b) end end,
 __pow = function(a, b)if type(b)==type({}) then return vec2(a.x^b.x,a.y^b.y) else return vec2(a.x^b,a.y^b) end end,
 __unm = function(a)if type(b)==type({}) then return vec2(-a.x,-a.y) else return vec2(a.x+b,a.y+b) end end,
 __idiv = function(a, b)if type(b)==type({}) then return vec2(a.x//b.x,a.y//b.y) else return vec2(a.x//b,a.y//b) end end,
 __tostring=function(a)return "x: ".. a.x .."  y: ".. a.y end
}

function vec2(x,y)
 local v={x=x or 0,y=y or 0}
 setmetatable(v,meta)
 return v
end


function lerp(a,b,t)
 return a*(1-t)+b*t
end


function check_colision(self, x, y)
 local x = self.pos.x + self.vel.x + self.acel.x + (x or 0)
 local y = self.pos.y + self.vel.y + self.acel.y + (y or 0)
 return solid[mget(x//8,y//8)] or false
end


--Global constants
solid={
 [16]=true,[17]=true,[18]=true,[32]=true,
 [33]=true,[34]=true,[48]=true,[49]=true,
 [50]=true
}
cell=8
rows=30
cols=17

plrs={}
function plrs:add(pos, player)
	local p = {
		id = player or #plrs+1,
		pos = pos or vec2(),
		vel = vec2(),
		velmax = 1.5, 
		acel = vec2(),
		spd = 1.2,
		size = {
			w=cell, h=cell*2
		},
		flip=0
	}
	table.insert(plrs,p)
end

function plrs:draw()
	vbank(1)
	for k, s in ipairs(plrs) do
		for k, cam in ipairs(cam) do 
			
			spr(
				256,
				s.pos.x-cam.pos.x,
				s.pos.y-cam.pos.y,
				15,
				1,
				s.flip,
				0,
				s.size.w/cell,
				s.size.h/cell
			)
		end
	end
end

function plrs:update()
	for k, s in ipairs(plrs) do
		local oldbtn=btn
		local oldbtnp=btnp
		local function btn(n) return oldbtn(((s.id-1)*8)+n) end
		local function btnp(n,n1,n2) return oldbtnp(((s.id-1)*8)+n,n1,n2) end
		  
		if btn(2) and s.vel.x>-s.velmax then
			s.acel.x = -s.spd / 8
			s.flip=1
		elseif btn(3) and s.vel.x<s.velmax  then
			s.acel.x = s.spd / 8
			s.flip=0
		else
			s.acel.x = 0
			s.vel.x = lerp(s.vel.x, s.acel.x, 0.1)
		end
		  
	  
		s.acel.y = grav
		for w = 0, s.size.w-2 do
			if check_colision(s, w, s.size.h-1) or check_colision(s, w, -1) then
				s.acel.y = 0
				s.vel.y = 0
				if btnp(4,-1,-1) and check_colision(s, w, s.size.h) then 
					s.acel.y = -3
					sfx(01,"C-2",17,0,7)
				end
			end
		 end
	  
		for h = 0, s.size.h-2 do
			if check_colision(s, s.size.w-1, h) or check_colision(s, -1, h) then
				s.acel.x=-s.vel.x 
			end
		end
		  
		--die
		if s.pos.y>cols*cell*cell then
	   
		--exit()
		end 
	  
		s.vel=s.vel+s.acel
		s.pos=s.pos+s.vel
	end
end 

cam={}
function cam:add(pos)
	local s={}
		s.pos=pos or vec2(0,0)
 
	table.insert(cam, s)
end

function cam:update()
	for k,s in ipairs(cam) do
		local pos=vec2(0,0)
		local i=0
		for k, p in ipairs(plrs) do
			pos=pos+p.pos
			i=i+1
		end
		pos.x=pos.x/i
		pos.y=pos.y/i
  
		s.pos.x=math.max(
			0,
			math.min(
				(240*8)-120,
				lerp(s.pos.x,pos.x-120, 0.05)
			)
		)
		s.pos.y=math.max(
			0,
			math.min(
				119*8,
				lerp(s.pos.y,pos.y-(68), 0.05)
			)
		)
 end
end

function cam:draw()
	for k,s in ipairs(cam) do
		map(
			s.pos.x//cell,
			s.pos.y//cell, 
			31, 
			18, 
			-(s.pos.x%cell),
			-(s.pos.y%cell)
		)
	end
end

local pressbutton = 0
function NewPlayer()
	if btn(12) then
		plrs:add(plrs[#plrs].pos,2)
	end
end

function init_GAME(maxPlayer)
	grav=0.14
	if #plrs<=maxPlayer-1 then
	plrs:add(vec2(cell+1,(cols*cell)*7))
	end
	cam:add(vec2(cell+1,(cols*cell)*7))
end

function GAME()
	--update
	plrs:update()
	cam:update()
	NewPlayer()
 
	--clear screem
	cls()
	vbank(0)
	cam:draw()
	--draw
	plrs:draw()
end

function init_MENU()
	Buttons={
		play={id=1,pos=vec2(15,15),res=vec2(print("play"),8)},
		setting={id=2,pos=vec2(15,25),res=vec2(print("setting"),8)},
		exit_={id=3,pos=vec2(15,36),res=vec2(print("exit"),8)}
		
	}
	menu_selector=nil
	 
end

function button_check(button, selector)
	local hit_box_view=true 
	if hit_box_view~=nil then
		rect(
			button.pos.x,
			button.pos.y,
			button.res.x,
			button.res.y,
			1
		)
	end
	if selector~=nil then
		if selector == button.id then
			return true
		else
			return false
		end
	else
		local mx, my, ml = mouse()
		for x = button.pos.x, button.pos.x+button.res.x do
			for y = button.pos.y, button.pos.y+button.res.y do
				if mx == x and my == y then
					if ml == true then
						return true
					else
						return false
					end
				end
			end
		end
	end
end

function _MENU()
	if btn(4) or menu_selector==nil then
		if button_check(Buttons.play, menu_selector) then
			gstate = "game" globaltime = 0 
		elseif button_check(Buttons.setting, menu_selector) then
			gstate = "setting" globaltime = 0 
		elseif button_check(Buttons.exit_, menu_selector) then
			gstate = "exit" globaltime = 0 
		end
	end
	if menu_selector~=nil then
	
		if btnp(0,15,15) and menu_selector>1 then
			menu_selector=menu_selector-1
		elseif btnp(1,15,15) and menu_selector<3 then
			menu_selector=menu_selector+1
		end
	elseif btn(0) or btn(1) then
		if  menu_selector==nil then
			menu_selector=1
		end
	end
	cls()
	if  menu_selector~=nil then
		rect(15,6+(menu_selector*9.75),40,8,0)
		rectb(14,5+(menu_selector*9.75),42,10,1)
	end
	print("play",16,16,1)
	print("setting",16,26,1)
	print("exit",16,37,1)
end

function init()
	t=0
	if gstate=="game" then
		init_GAME(1)
	end
	if gstate=="menu" then
		init_MENU()
	end
	if gstate=="setting" then
		
	end
	if gstate=="exit" then
		exit()
	end
end

function BOOT()
	init()
end
globaltime=0
gstate="game"
function TIC()
	if globaltime<2 then init() end
	if gstate=="game" then
		GAME()
	end
	if gstate=="menu" then
		_MENU()
	end
	t=t+1
	globaltime=globaltime+1
end

